async function load() { loading.value = true; error.value = ''; try { if (view.value !== 'import') metrics.value = await api.overview(period.value, perspective.value, scope.value); readiness.value = await api.readiness(batchNo.value); quality.value = await api.quality(batchNo.value); datasets.value = await api.datasets(perspective.value); source.value = 'api'; if (view.value === 'result') results.value = (await api.result(batchNo.value)).pnls; if (view.value === 'pvm') pvmRows.value = await api.pvm(batchNo.value); if (view.value === 'tree') treeRows.value = await api.metricTree(batchNo.value); if (view.value === 'ai') aiDraft.value = await api.ai(batchNo.value); if (view.value === 'metrics') configMetrics.value = await api.metrics(perspective.value, true); if (view.value === 'mapping') mappingRows.value = await api.mappings(mappingType.value, true) } catch (e) { loadDemo(); error.value = `后端暂不可用，已切换脱敏演示数据：${e instanceof Error ? e.message : '请求失败'}` } finally { loading.value = false } }; async function generateAi() { try { aiDraft.value = await api.generateAi(batchNo.value); source.value = 'api'; showToast('AI分析草稿已生成') } catch { loadDemo(); showToast('当前展示规则引擎演示草稿') } }; async function submitImport() { if (!selectedDataset.value || !selectedFile.value) { importMessage.value = '请选择数据集并上传 Excel 文件。'; return } try { await api.createBatch({ batchNo: batchNo.value, period: period.value, perspective: perspective.value }); const task = await api.createImport(batchNo.value, { datasetCode: selectedDataset.value, fileName: selectedFile.value.name }); await api.validateImport(task.taskNo, selectedFile.value); importMessage.value = `校验完成：${selectedFile.value.name}，请刷新批次完整性。`; await load() } catch (e) { importMessage.value = e instanceof Error ? e.message : '导入失败，已保留当前演示数据。' } }; async function saveMetric() { if (!metricForm.value.metricCode || !metricForm.value.metricName || !metricForm.value.formulaExpression) { configMessage.value = '指标编码、名称和公式不能为空。'; return } try { const save