        <section v-else-if="view === 'import'" class="view active"><div class="section-head"><div><h2>月度数据导入</h2><p>总部财经按月创建批次，整期覆盖导入业务数据后统一校验和计算</p></div><span class="tag">当前批次：{{ readiness?.readyForCalculation ? '待计算' : '需修正' }}</span></div><div class="stepper"><div class="step done"><b>✓</b>创建批次</div><div class="step done"><b>✓</b>上传月度数据</div><div class="step current"><b>3</b>校验映射</div><div class="step"><b>4</b>统一计算</div><div class="step"><b>5</b>确认发布</div></div><div class="upload-grid"><div class="panel"><div class="panel-title">本月业务数据文件 <small>整期覆盖导入</small></div><div class="upload-box"><div class="upload-icon">⇧</div><div>将财经月度明细表拖入此处，或选择文件</div><label for="fileInput">选择文件</label><input id="fileInput" type="file" accept=".xlsx,.xls,.csv" @change="pickFile"><div class="muted">支持预算、收入成本、期间费用、减值结果、闲置费用等月度文件</div></div><div class="file-list"><div class="file"><span>收入成本明细_202608.xlsx</span><em>已通过模板校验</em></div><div class="file"><span>期间费用_202608.xlsx</span><em>已通过模板校验</em></div><div class="file"><span>闲置费用_202608.xlsx</span><em>已通过模板校验</em></div></div></div><div class="panel"><div class="panel-title">月度批次校验结果</div><div class="kpi-grid"><div class="kpi"><small>文件数量</small><b>3</b><span class="muted"> 个</span></div><div class="kpi"><small>有效记录</small><b>12,684</b><span class="muted"> 行</span></div><div class="kpi"><small>未匹配记录</small><b class="heat">26</b><span class="muted"> 行</span></div></div><div class="alert" style="margin-top:14px"><strong>需要财经确认：</strong>发现26条映射未匹配记录，金额合计¥42.6万。忽略记录不会进入结果，但会保留操作痕迹。</div><div class="action-row"><button class="btn" @click="showToast('已打开未匹配明细（Demo）')">查看未匹配</button><button class="btn ghost" @click="showToast('已忽略并留痕（Demo）')">忽略并留痕</button><button class="btn primary" @click="selectedDataset = datasets[0]?.code || ''; submitImport()">开始计算</button></div></div></div><div class="panel" style="margin-top:15px"><div class="panel-title">数据集与完整性检查 <small>基地数据集与产品线/事业部数据集分别上传、分别校验</small></div><div class="dataset-grid"><div v-for="row in readiness?.datasets" :key="row.datasetCode" class="dataset-card"><strong>{{ row.datasetName }}</strong><small>{{ row.required ? '必需' : '可选' }} · <span :class="row.status === 'VALID' ? 'green' : 'red'">{{ row.status }}</span></small></div></div></div><div v-if="importMessage" class="alert" style="margin-top:12px">{{ importMessage }}</div></section>
        <section v-else-if="view === 'pvm'" class="view active"><div class="section-head"><div><h2>PVM因素分析</h2><p>支持期间、基地、项目、客户组合筛选，结果按电芯型号汇总</p></div><div><span class="tag">正式结果勾稽差异：0</span><button class="btn" @click="exportView('PVM')">导出</button></div></div><div class="panel"><div class="pvm-filter"><label class="muted">筛选：</label><select><option>全部基地</option><option>南昌</option><option>义乌</option><option>泰国</option></select><select><option>全部项目</option><option>项目A</option><option>项目B</option></select><select><option>全部客户简称</option><option>深陶</option><option>柳汽</option></select><select><option>全部电芯型号</option><option>106Ah</option><option>217Ah</option></select><button class="btn primary" @click="showToast('已按当前条件刷新PVM结果')">刷新分析</button></div><div class="kpi-grid"><div class="kpi"><small>收入GAP</small><b class="green">+¥1,062万</b><span class="muted">实际高于预算</span></div><div class="kpi"><small>毛利GAP</small><b class="red">-¥286万</b><span class="muted">成本影响为主</span></div><div class="kpi"><small>毛利率变化</small><b class="red">-1.8<span>pp</span></b><span class="muted">预算19.9% → 实际18.1%</span></div></div></div><div class="panel" style="margin-top:15px"><div class="panel-title">电芯型号PVM拆解 <small>金额单位：万元</small></div><div class="table-scroll"><table><thead><tr><th>电芯型号</th><th>电量预算</th><th>电量实际</th><th>收入GAP</th><th>价格影响</th><th>销量影响</th><th>材料成本影响</th><th>综合判断</th></tr></thead><tbody><tr v-for="row in pvmRows" :key="row.scopeCode"><td><b>{{ row.scopeCode }}</b></td><td>{{ row.budgetVolume }}</td><td>{{ row.actualVolume }}</td><td :class="row.revenueGap >= 0 ? 'green' : 'red'">{{ row.revenueGap >= 0 ? '+' : '' }}{{ row.revenueGap }}</td><td class="green">+116</td><td :class="row.volumeGap >= 0 ? 'green' : 'red'">{{ row.volumeGap >= 0 ? '+' : '' }}{{ row.volumeGap }}</td><td :class="row.costGap <= 0 ? 'green' : 'red'">{{ row.costGap }}</td><td><span :class="['status', row.grossProfitGap >= 0 ? 'ok' : 'warn']">{{ row.grossProfitGap >= 0 ? '综合改善' : '成本预警' }}</span></td></tr></tbody></table></div></div></section>
        <section v-else-if="view === 'permission'" class="view active"><div class="section-head"><div><h2>权限验证</h2><p>切换角色后，系统入口、行级数据和操作权限同步变化</p></div><span class="tag">服务端行级过滤 · Demo验证</span></div><div class="permission-callout"><b>验证方法：</b>切换角色或授权基地，再尝试进入页面、查看损益、导出数据及生成/发布AI分析。</div><div class="panel"><div class="pvm-filter"><label class="muted">当前角色：</label><select v-model="currentRole" @change="changeRole"><option>总部财经</option><option>基地财经</option><option>基地巴长</option><option>基地运营</option></select><span class="muted">授权对象：</span><select v-model="roleScope"><option>全部基地</option><option>南昌基地</option><option>宜昌基地</option><option>义乌基地</option><option>泰国基地</option></select><button class="btn" @click="showToast('授权已保存（Demo）')">保存授权</button></div><table><thead><tr><th>能力</th><th>当前角色权限</th><th>页面表现</th><th>授权范围</th></tr></thead><tbody><tr v-for="row in [['经营看板','可查看','显示授权范围汇总、趋势和排名'],['损益计算结果','可查看','可下钻授权范围损益'],['月度数据导入',currentRole === '总部财经' ? '可编辑' : '只读','按角色控制上传和统一计算'],['配置维护',currentRole === '总部财经' ? '可编辑' : '只读','维护映射和费用分类'],['AI分析发布',currentRole === '总部财经' ? '可发布' : '不可用','草稿、确认和分发受控']]" :key="row[0]"><td>{{ row[0] }}</td><td><span :class="['status', row[1] === '不可用' ? 'gray' : row[1] === '只读' ? 'warn' : 'ok']">{{ row[1] }}</span></td><td>{{ row[2] }}</td><td>{{ roleScope }}</td></tr></tbody></table></div></section>
        <section v-else-if="view === 'ai'" class="view active"><div class="section-head"><div><h2>AI经营分析</h2><p>财经点击生成草稿，AI读取授权范围内明细并给出解释性分析</p></div><span class="tag">结果版本：RV-202608-01</span></div><div class="permission-callout"><b>AI分析状态：</b>仅解释已计算结果，不改写正式财务数据；正式发布前需财经确认。</div><div class="ai-box"><div class="ai-top"><div class="ai-icon">✦</div><div class="ai-title">财经AI分析助手<small>仅读取已校验结果和授权明细，不参与财务计算</small></div><span class="spacer"></span><button class="btn primary" @click="generateAi">生成分析草稿</button></div><div v-if="aiDraft" class="ai-content"><div v-for="(text, name) in aiDraft.sections" :key="name" class="ai-section"><h4>{{ name }}</h4><p>{{ text }}</p></div><div class="action-row"><button class="btn" @click="showToast('AI草稿已保存，等待财经确认')">保存草稿</button><button class="btn primary" @click="showToast('AI分析已确认并发布（Demo）')">确认并发布</button></div></div></div></section>
        <section v-else-if="view === 'gross'" class="view active"><div class="section-head"><div><h2>毛利分析</h2><p>按当期/累计查看收入与毛利变化 · <span class="scope-chip">{{ activeScopeText }}</span></p></div><div><button class="btn" :class="{ primary: grossPeriod === '当期' }" @click="grossPeriod = '当期'">当期</button> <button class="btn" :class="{ primary: grossPeriod === '累计' }" @click="grossPeriod = '累计'">累计</button></div></div><div class="kpi-grid"><div class="kpi"><small>收入分析</small><b class="green">+¥1,062万</b><span class="muted">销量 +¥312万 · 单位收入 +¥116万</span></div><div class="kpi"><small>毛利分析</small><b class="red">-¥286万</b><span class="muted">销量、单位收入改善被单位成本抵消</span></div><div class="kpi"><small>单位成本</small><b class="red">+¥0.08/Wh</b><span class="muted">材料 + 人工 + 外协 + 变动/固定制费</span></div></div><div class="chart-grid"><div class="panel"><div class="panel-title">收入分析 <small>预算 vs 实际</small></div><div class="chart-bars"><div v-for="bar in [72,64,82,78]" :key="bar" class="bar-group"><i class="bar plan" :style="{ height: `${bar - 10}%` }"></i><i class="bar" :style="{ height: `${bar}%` }"></i></div></div><div class="chart-labels"><span>销量</span><span>单位收入</span><span>收入合计</span><span>收入GAP</span></div></div><div class="panel"><div class="panel-title">毛利分析 <small>影响因素拆解</small></div><div class="chart-bars"><div v-for="bar in [58,68,42,65]" :key="bar" class="bar-group"><i class="bar plan" :style="{ height: `${bar + 14}%` }"></i><i class="bar" :style="{ height: `${bar}%` }"></i></div></div><div class="chart-labels"><span>销量</span><span>单位收入</span><span>单位成本</span><span>毛利GAP</span></div></div></div><div class="ai-box gross-ai"><div class="ai-top"><div class="ai-icon">✦</div><div class="ai-title">毛利AI简析<small>基于当前授权范围及已计算结果生成</small></div></div><div class="ai-content"><div class="ai-section"><h4>收入分析</h4><p>收入差异主要由销量和单位收入共同影响，建议结合基地、客户项目和电芯型号进一步定位。</p></div><div class="ai-section"><h4>毛利分析</h4><p>毛利未随收入同步改善，核心线索为单位成本上升；单位成本按材料、人工、外协、制造变动和制造固定制费拆解。</p></div></div></div></section>
        <section v-else-if="view === 'matrix'" class="view active"><div class="section-head"><div><h2>事业部视角：基地 × 产品交叉矩阵</h2><p>经营分析利润 = 收入 - 销售成本 - 经营分析费用；剔除研发、运营、减值</p></div><label>指标<select v-model="matrixMetric"><option value="REVENUE">收入</option><option value="GROSS">毛利</option><option value="PROFIT">经营分析利润</option></select></label></div><div class="permission-callout"><b>口径边界：</b>当前为脱敏演示数据；正式上线前需冻结利润剔除项和基地/产品主数据映射。</div><div class="panel table-scroll"><table class="matrix-table"><thead><tr><th>基地</th><th>产品</th><th>当前值</th><th>基准值</th><th>绝对GAP</th><th>GAP%</th><th>经营判断</th></tr></thead><tbody><tr v-for="row in matrixRows" :key="`${row.base}-${row.product}`"><td>{{ row.base }}</td><td>{{ row.product }}</td><td>{{ format(matrixMetric, matrixPair(row)[0]) }}</td><td>{{ format(matrixMetric, matrixPair(row)[1]) }}</td><td :class="matrixPair(row)[0] - matrixPair(row)[1] >= 0 ? 'green' : 'red'">{{ format(matrixMetric, matrixPair(row)[0] - matrixPair(row)[1]) }}</td><td>{{ matrixPair(row)[1] ? `${((matrixPair(row)[0] - matrixPair(row)[1]) / Math.abs(matrixPair(row)[1]) * 100).toFixed(1)}%` : '—' }}</td><td>{{ matrixPair(row)[0] - matrixPair(row)[1] >= 0 ? '贡献提升' : '需下钻' }}</td></tr><tr class="matrix-total"><td colspan="2">合计</td><td>{{ format(matrixMetric, matrixTotal().current) }}</td><td>{{ format(matrixMetric, matrixTotal().base) }}</td><td>{{ format(matrixMetric, matrixTotal().current - matrixTotal().base) }}</td><td>—</td><td>按当前筛选口径汇总</td></tr></tbody></table></div></section>
        <section v-else-if="view === 'unit'" class="view active"><div class="section-head"><div><h2>单位效率分析</h2><p>线体单位制造费用与 YU 指标卡</p></div><span class="tag">{{ v13Unit?.status || '待加载' }}</span></div><div class="unit-grid"><article class="panel"><div class="panel-title">线体单位制造费用 <small>单位：元 / Wh</small></div><table v-if="unitRows.length"><thead><tr><th>基地</th><th>线体</th><th>制造费用</th><th>产出Wh</th><th>元/Wh</th><th>环比</th></tr></thead><tbody><tr v-for="row in unitRows" :key="`${row[0]}-${row[1]}`"><td>{{ row[0] }}</td><td>{{ row[1] }}</td><td>{{ row[2] }}</td><td>{{ row[3] }}</td><td>{{ row[4] }}</td><td :class="row[5].startsWith('+') ? 'red' : 'green'">{{ row[5] }}</td></tr></tbody></table><div v-else class="placeholder-card">后端尚未返回可发布的线体单位费用。</div><div class="formula-box">{{ v13Unit?.blockers?.join('；') || '待确认分母、费用范围和产出数据源。' }}</div></article><article class="panel"><div class="panel-title">YU 指标卡与12个月趋势 <small>口径冻结后接入</small></div><div class="placeholder-card"><div class="metric">待定义</div><small>{{ v13Unit?.notes?.join('；') || '当前不写入正式经营结论' }}</small></div><div class="trend-bars"><i v-for="(bar,index) in [42,55,61,58,67,74,69,78,82,76,88,91]" :key="index" class="trend-bar" :style="{ height: `${bar}%` }"></i></div><div class="trend-labels"><span>趋势占位</span><span>待YU接口</span></div><div class="formula-box">YU 指标需确认定义、数据来源、单位和目标值后接入正式服务。</div></article></div></section>
        <section v-else-if="view === 'forecast'" class="view active"><div class="section-head"><div><h2>FC滚动预测与BGT / ACT三口径</h2><p>当前选择：{{ fcVersion }} · 支持版本导入、冻结、对比与追溯</p></div><span class="v13-badge">{{ scenarioLabel }}</span></div><div class="permission-callout"><b>版本治理：</b>FC不在平台内在线编制；正式预测由预算/经营系统生成后按版本导入。<span v-if="v13Forecast?.blockers?.length">当前状态：{{ v13Forecast.blockers.join('；') }}</span></div><div v-if="forecastRows.length" class="panel table-scroll"><table><thead><tr><th>指标</th><th>BGT</th><th>ACT</th><th>FC</th><th>ACT-BGT</th><th>ACT-FC</th><th>FC-BGT</th></tr></thead><tbody><tr v-for="row in forecastRows" :key="String(row.metricCode || row.metricName)"><td>{{ row.metricName || row.metricCode }}</td><td>{{ format(String(row.metricCode || 'REVENUE'), Number(row.budget || 0)) }}</td><td>{{ format(String(row.metricCode || 'REVENUE'), Number(row.actual || 0)) }}</td><td>{{ row.fc == null ? '待接入' : format(String(row.metricCode || 'REVENUE'), Number(row.fc)) }}</td><td>{{ format(String(row.metricCode || 'REVENUE'), Number(row.actual || 0) - Number(row.budget || 0)) }}</td><td>{{ row.fc == null ? '—' : format(String(row.metricCode || 'REVENUE'), Number(row.actual || 0) - Number(row.fc)) }}</td><td>{{ row.fc == null ? '—' : format(String(row.metricCode || 'REVENUE'), Number(row.fc) - Number(row.budget || 0)) }}</td></tr></tbody></table></div><div v-else class="alert">当前 FC 接口未返回可发布快照，页面不再使用演示三口径数字。</div><div class="panel waterfall-panel"><div class="panel-title">单位毛利GAP瀑布拆解 <small>来自后端 PVM 因素</small></div><div v-if="waterfallFactors.length" class="waterfall"><div v-for="factor in waterfallFactors" :key="String(factor.code)" class="water-step"><div class="water-bar" :class="Number(factor.value || 0) >= 0 ? 'good' : 'bad'" :style="{ height: `${Math.max(18, Math.abs(Number(factor.value || 0)) * 6)}px` }">{{ Number(factor.value || 0) > 0 ? '+' : '' }}{{ format('REVENUE', Number(factor.value || 0)) }}</div><small>{{ factor.code }}</small></div></div><div v-else class="placeholder-card">当前后端未返回瀑布因子。</div><div class="formula-box">正式单位毛利仍需冻结单位分母；当前展示后端返回的正式 PVM 因素，不再读取前端演示常量。</div></div></section>
        <section v-else-if="view === 'risk'" class="view active"><div class="risk-sheet"><div class="section-head"><div><h2>经营分析风险提示 · 一页纸</h2><p>{{ period }} · {{ perspectiveName }}视角 · {{ scenarioLabel }}</p></div><button class="btn primary" @click="printRisk">打印 / 导出PDF</button></div><div class="risk-summary"><div class="risk-kpi"><small>总体风险</small><b :class="v13Risk?.risks?.length ? 'risk-level-high' : 'green'">{{ v13Risk?.risks?.length ? '需关注' : '未发现负向偏差' }}</b></div><div class="risk-kpi"><small>需关注事项</small><b>{{ v13Risk?.risks?.length || 0 }}</b></div><div class="risk-kpi"><small>待确认口径</small><b class="risk-level-mid">{{ v13Risk?.blockers?.length || 0 }}</b></div><div class="risk-kpi"><small>数据状态</small><b :class="v13Risk?.status === 'CALCULATED' ? 'green' : 'risk-level-mid'">{{ v13Risk?.status || '待加载' }}</b></div></div><div class="decision-strip"><span class="decision-chip">结果版本：{{ v13Risk?.versionNo || '待加载' }}</span><span class="decision-chip">阈值：后端状态 {{ v13Risk?.status || '待加载' }}</span><span class="decision-chip">发布前需责任人确认</span></div><table><thead><tr><th>等级</th><th>领域</th><th>风险/异常</th><th>责任角色</th><th>建议动作</th><th>状态</th></tr></thead><tbody><tr v-for="row in riskRows" :key="row[1]"><td><span :class="row[0] === '高' ? 'red' : row[0] === '中' ? 'warning' : 'green'">{{ row[0] }}</span></td><td>{{ row[1] }}</td><td>{{ row[2] }}</td><td>{{ row[3] }}</td><td>{{ row[4] }}</td><td>{{ row[5] }}</td></tr></tbody></table><div class="pnl-note">风险等级由后端确定性规则和阈值状态返回；阈值未冻结时只展示观察项，不替代正式风险审批。</div></div></section>
        <section v-else-if="view === 'topics'" class="view active"><div class="section-head"><div><h2>P1专题分析</h2><p>{{ activeTopicData.name }} · {{ activeTopicPayload?.notes?.join('；') || activeTopicData.note }}</p></div><span class="tag">{{ activeTopicPayload?.status || '待加载' }}</span></div><div class="topic-buttons"><button v-for="(topic,key) in p1Topics" :key="key" class="btn" :class="{ primary: activeTopic === key }" @click="activeTopic = key">{{ topic.name }}</button></div><div class="panel table-scroll"><table v-if="topicDisplayRows.length"><thead><tr><th v-for="header in activeTopicData.headers" :key="header">{{ header }}</th></tr></thead><tbody><tr v-for="(row,index) in topicDisplayRows" :key="index"><td v-for="cell in row" :key="cell">{{ cell }}</td></tr></tbody></table><div v-else class="placeholder-card">当前专题尚未接入明细源数据，页面只展示后端阻断状态。</div><div class="formula-box">{{ activeTopicPayload?.blockers?.join('；') || '待P0口径冻结、字段映射与权限范围确认。' }}</div></div></section>
        <section v-else-if="view === 'configImport' || view === 'mapping' || view === 'metrics'" class="view active"><div class="section-head"><div><h2>{{ title }}</h2><p>基础配置、映射关系和指标展示由总部财经维护，导入与月度业务数据分离</p></div><span class="tag">增量维护 · 保留审计</span></div><div class="permission-callout"><b>权限边界：</b>配置导入先校验匹配键、重复项和口径，不直接替代已发布业务数据。</div><div class="panel" v-if="view === 'configImport'"><div class="config-form"><select v-model="configImportType"><option>SALES_PROJECT_MAPPING</option><option>INVENTORY_MAPPING</option><option>EXPENSE_CATEGORY</option><option>EXPENSE_ALLOCATION</option><option>FX_RATE</option><option>USER_PERMISSION</option></select><input type="file" accept=".xlsx,.xls,.csv" @change="pickConfigFile"><button class="btn primary" @click="uploadConfig">上传配置文件</button></div><div v-if="configImportMessage" class="alert">{{ configImportMessage }}</div><table><thead><tr><th>配置对象</th><th>典型文件/来源</th><th>维护方式</th><th>最近批次</th><th>状态</th></tr></thead><tbody><tr><td>销售项目映射</td><td>销售项目清单-202608.xlsx</td><td>增量导入＋失效维护</td><td>2026-08-31</td><td><span class="status ok">有效</span></td></tr><tr><td>费用分类字典</td><td>2608费用匹配表.xlsx</td><td>每月增量导入</td><td>2026-08-31</td><td><span class="status ok">有效</span></td></tr><tr><td>角色权限名单</td><td>用户角色权限名单</td><td>增量导入＋授权确认</td><td>2026-08-31</td><td><span class="status ok">有效</span></td></tr></tbody></table></div><div class="panel" v-else-if="view === 'mapping'"><div class="config-form"><select v-model="mappingType"><option>SALES_PROJECT</option><option>INVENTORY</option><option>EXPENSE_RULE</option><option>FX_RATE</option></select><input v-model="mappingForm.matchKey" placeholder="匹配键"><input v-model="mappingForm.mappedValue" placeholder="映射值"><button class="btn primary" @click="saveMapping">新增映射</button></div><table><thead><tr><th>映射类型</th><th>匹配条件</th><th>输出归属</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in mappingRows" :key="`${row.type}-${row.matchKey}`"><td>{{ row.type }}</td><td>{{ row.matchKey }}</td><td>{{ row.mappedValue }}</td><td><span :class="['status', row.enabled ? 'ok' : 'gray']">{{ row.enabled ? '有效' : '停用' }}</span></td><td><button v-if="row.enabled" class="link-button" @click="disableMapping(row)">停用</button></td></tr></tbody></table></div><div class="panel" v-else><div class="config-form"><input v-model="metricForm.metricCode" placeholder="指标编码"><input v-model="metricForm.metricName" placeholder="指标名称"><input v-model="metricForm.formulaExpression" placeholder="公式，如 SUM(REVENUE)"><button class="btn primary" @click="saveMetric">保存指标</button></div><div v-if="configMessage" class="alert">{{ configMessage }}</div><table><thead><tr><th>展示</th><th>指标名称</th><th>指标编码</th><th>单位</th><th>适用视角</th><th>状态</th></tr></thead><tbody><tr v-for="row in configMetrics" :key="row.metricCode"><td><input type="checkbox" :checked="row.enabled"></td><td>{{ row.metricName }}</td><td>{{ row.metricCode }}</td><td>{{ row.unit }}</td><td>{{ row.applicablePerspective }}</td><td><span :class="['status', row.enabled ? 'ok' : 'gray']">{{ row.enabled ? '启用' : '停用' }}</span></td></tr></tbody></table></div></section>
        <section v-else-if="view === 'users' || view === 'menus' || view === 'audit'" class="view active"><div class="section-head"><div><h2>{{ title }}</h2><p>维护平台权限、菜单顺序并保留导入、修正、计算、发布、AI生成的追溯信息</p></div><span class="tag">不可篡改审计链</span></div><div class="panel" v-if="view === 'users'"><table><thead><tr><th>姓名</th><th>工号</th><th>用户角色</th><th>数据视角</th><th>可查看范围</th><th>状态</th></tr></thead><tbody><tr><td>演示用户A</td><td>DEMO001</td><td>总部财经</td><td>全部</td><td>全部基地、产品线、事业部</td><td><span class="status ok">有效</span></td></tr><tr><td>演示用户B</td><td>DEMO002</td><td>基地财经</td><td>基地</td><td>南昌基地、宜昌基地</td><td><span class="status ok">有效</span></td></tr><tr><td>演示用户C</td><td>DEMO003</td><td>基地巴长</td><td>基地</td><td>泰国基地</td><td><span class="status ok">有效</span></td></tr></tbody></table></div><div class="panel" v-else-if="view === 'menus'"><table><thead><tr><th>菜单名称</th><th>菜单编码</th><th>分组</th><th>当前顺序</th><th>状态</th></tr></thead><tbody><tr v-for="(group,index) in navGroups.flatMap(g => g.items)" :key="group[0]"><td>{{ group[1] }}</td><td>{{ String(group[0]).toUpperCase() }}</td><td>{{ index < 7 ? '平台功能' : index < 13 ? 'V1.3分析' : '配置与追溯' }}</td><td>{{ index + 1 }}</td><td><span class="status ok">启用</span></td></tr></tbody></table></div><div class="panel" v-else><table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>对象</th><th>结果</th></tr></thead><tbody><tr><td>2026-09-17 09:12</td><td>总部财经</td><td>导入数据</td><td>收入成本明细_202608.xlsx</td><td><span class="status ok">成功</span></td></tr><tr><td>2026-09-17 09:25</td><td>总部财经</td><td>忽略未匹配</td><td>批次 202608-01 · 26条</td><td><span class="status warn">已留痕</span></td></tr><tr><td>2026-09-17 09:36</td><td>总部财经</td><td>开始计算</td><td>批次 202608-01</td><td><span class="status ok">成功</span></td></tr><tr><td>2026-09-17 09:41</td><td>总部财经</td><td>生成AI草稿</td><td>批次 202608-01</td><td><span class="status gray">待确认</span></td></tr></tbody></table></div></section></main></div><div v-if="toastMessage" class="toast show">{{ toastMessage }}</div></div>
</template>

